package com.nova.security;
import com.nova.auth.UserRepository; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.security.core.userdetails.UserDetailsService; import org.springframework.security.core.userdetails.UsernameNotFoundException; import org.springframework.stereotype.Service;
@Service public class CustomUserDetailsService implements UserDetailsService {private final UserRepository users; public CustomUserDetailsService(UserRepository users){this.users=users;} @Override public UserDetails loadUserByUsername(String email){var u=users.findByEmailIgnoreCase(email).orElseThrow(()->new UsernameNotFoundException("User not found"));return org.springframework.security.core.userdetails.User.withUsername(u.getEmail()).password(u.getPassword()).authorities("ROLE_"+u.getRole().name()).build();}}
